'use client'

import { useState } from 'react'
import { Menu, X } from 'lucide-react'

import { Sheet, SheetContent, SheetTitle, SheetTrigger } from '../../components/ui/sheet'
import { ProductMark } from '../../components/ui/product-mark'
import type { ProductMarkProps } from '../../components/ui/product-mark'

/** One destination in the mobile panel, which is the site's own navigation. */
export type MobileNavLink = {
  /** The text of the link. */
  label: string
  /** Where the link goes. */
  href: string
  /** Marks the link as the page the reader is on. */
  current?: boolean
}

/**
 * A group of destinations in the mobile panel, as a label above its links.
 *
 * The row renders a group as a menu because a row is short of room and a group
 * is one control there; this panel is not short of room, so the same group is a
 * named run of the list rather than a second thing to open. A reader below the
 * row's threshold therefore meets every destination flat: no route is behind
 * two disclosures, and the group's name still tells them which destinations
 * belong together.
 */
export type MobileNavGroup = {
  /** The group's own name, which is a label and not a link. */
  label: string
  /** The destinations under the label, in the order a reader should meet them. */
  children: readonly MobileNavLink[]
}

/** One entry in the mobile panel: a link, or a group of them. */
export type MobileNavEntry = MobileNavLink | MobileNavGroup

/** The props the mobile navigation takes. */
export type MobileNavProps = {
  /** The product this navigation belongs to, drawn as the mark above the list. */
  product: Pick<ProductMarkProps, 'id' | 'name' | 'pack' | 'mark'>
  /** Every destination, in the order a reader should meet them. */
  links: readonly MobileNavEntry[]
  /** The accessible name of the panel, which is also the trigger's name. */
  label: string
  /** The word on the trigger while the panel is closed. */
  openLabel: string
  /** The word on the trigger while the panel is open. */
  closeLabel: string
}

/**
 * The navigation for viewports below the row's own threshold.
 *
 * **It carries every destination, not a subset.** From the narrowest phone up to
 * the width the horizontal row is authored for, this panel is the only way to reach
 * a section of the site, so a link the row shows at `lg` and the panel omits at
 * 640 is a route a reader on a small laptop cannot find at all. Both render the one
 * array, so a destination added to one is in the other by construction rather than
 * by remembering twice.
 *
 * **It is a Sheet rather than a disclosure panel of the navbar's own, and the
 * difference is the overlay.** A panel that is a child of the bar sits over the
 * page with the bar still visible and nothing above the rest of the document, so
 * scrolling the page behind it moves content the reader thought was dismissed. A
 * sheet owns a modal surface: the rest of the page is not reachable, Escape closes
 * it, and focus is held inside it and handed back to the trigger on the way out.
 * That is the behaviour a full-width menu over a long page needs, and it is the
 * behaviour Prism's own navigation had to hand-write.
 *
 * The links are full width with a 44 pixel minimum height, because below the row's
 * threshold this is a touch target and not a line of text, and the coarse-pointer
 * floor in the design system asks for exactly that. A group's label is a
 * `role="group"` named by the label, so a reader who navigates the panel by
 * landmark or by list is told which links belong together rather than meeting a
 * longer list with a break in it.
 */
export function MobileNav({
  product,
  links,
  label,
  openLabel,
  closeLabel,
}: MobileNavProps) {
  const [open, setOpen] = useState(false)

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger
        data-slot="site-navbar-mobile-trigger"
        aria-label={open ? closeLabel : openLabel}
        className="border-border bg-card text-foreground hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex size-11 shrink-0 items-center justify-center rounded-full border transition-colors focus-visible:ring-[3px] focus-visible:outline-none lg:hidden"
      >
        {open ? <X aria-hidden className="size-5" /> : <Menu aria-hidden className="size-5" />}
      </SheetTrigger>

      <SheetContent side="right" className="w-80">
        <SheetTitle className="sr-only">{label}</SheetTitle>
        <nav aria-label={label} className="flex flex-col gap-1">
          <div className="mb-4 flex items-center">
            <ProductMark
              id={product.id}
              name={product.name}
              pack={product.pack}
              mark={product.mark}
              size="md"
            />
          </div>
          {links.map((entry) =>
            'children' in entry ? (
              <div
                key={entry.label}
                role="group"
                aria-label={entry.label}
                className="mt-5 flex flex-col gap-1"
              >
                {/*
                  The label rhymes with the sidebar's own group labels, because
                  the two are the same thing said on two surfaces: a `text-sm
                  font-semibold tracking-tight` muted label, with no hover and no
                  route, since a label that behaved like a link would be a
                  destination pretending it had no children. Its padding below
                  is the sidebar's own rhythm: more room after a heading than
                  between two links, so the group reads as held by the label
                  rather than as a link that happens to be bold.
                */}
                <span className="text-muted-foreground px-3 pb-2 text-sm font-semibold tracking-tight">
                  {entry.label}
                </span>
                {entry.children.map((link) => (
                  <PanelLink key={link.href} link={link} onNavigate={() => setOpen(false)} />
                ))}
              </div>
            ) : (
              <PanelLink key={entry.href} link={entry} onNavigate={() => setOpen(false)} />
            ),
          )}
        </nav>
      </SheetContent>
    </Sheet>
  )
}

/** One link in the panel, extracted because the group and the root render the same one. */
function PanelLink({ link, onNavigate }: { link: MobileNavLink; onNavigate: () => void }) {
  return (
    <a
      href={link.href}
      aria-current={link.current ? 'page' : undefined}
      onClick={onNavigate}
      className={
        link.current
          ? 'bg-accent text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex min-h-11 items-center rounded-lg px-3 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:outline-none'
          : 'text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-ring flex min-h-11 items-center rounded-lg px-3 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:outline-none'
      }
    >
      {link.label}
    </a>
  )
}

'use client'

import { ChevronDown } from 'lucide-react'

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '../../components/ui/dropdown-menu'
import type { SiteNavLink } from './site-navbar'

/** One destination inside the menu, with the current flag already resolved. */
export type NavMenuLink = SiteNavLink & {
  /** Marks this destination as the page the reader is on. */
  current: boolean
}

/** The props the navigation menu takes. */
export type NavMenuProps = {
  /** The word on the trigger, which is the group's own name. */
  label: string
  /** The group's destinations, in the order a reader should meet them. */
  links: readonly NavMenuLink[]
  /**
   * Marks the group as holding the page the reader is on, which the bar
   * resolves against its own `currentPath` before it crosses the client
   * boundary. The trigger carries the same persistent underline a current link
   * on the row carries, so the place the reader is on is named on the row even
   * with the menu shut, by a mark that is shape rather than colour.
   */
  current: boolean
}

/**
 * One group of the site's own destinations, as a menu.
 *
 * A bar whose navigation is a row of links clubs into groups the moment a site
 * outgrows the row: five destinations that are all "the parts of the library"
 * beside four that are each a body of knowledge is a row a reader scans
 * word by word rather than recognises at a glance. This is the second half of
 * that row, and it is the one control in the row, because a group is not a
 * destination: it is a place other destinations live behind.
 *
 * **The items are links, not commands, for the reason the sites menu states.**
 * A menu item that navigated would be a command wearing a link's clothes, and
 * a reader who middle-clicks a row that only looks like a link gets no new tab.
 * Each item is rendered as the anchor itself rather than wrapping one, so the
 * row is one tab stop and one target.
 *
 * **The menu is a closed group, and a closed group shows nothing.** A reader
 * with scripting off sees the trigger and cannot open it, which is why the bar
 * renders a group as a menu only on the row above the panel threshold: below
 * it, the sheet lists every destination flat, and the bar's caller keeps
 * whatever routes it cannot afford to hide out of a group. The trigger is
 * filled when the reader is inside the group, so the place they are is on the
 * row even with the menu shut.
 *
 * **The chevron rotates on the open state and on nothing else.** Something
 * happened and the reader can see that it did, at the authored duration, and
 * the rotation, with the persistent underline a current trigger carries, is the
 * whole of the motion here.
 */
export function NavMenu({ label, links, current }: NavMenuProps) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        data-slot="site-navbar-nav-trigger"
        data-current={current ? 'true' : undefined}
        className={
          current
            ? 'group data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground text-foreground focus-visible:border-ring focus-visible:ring-ring relative gap-1 rounded-md px-2 py-1.5 text-sm font-medium transition-colors after:absolute after:inset-x-2 after:bottom-0.5 after:h-0.5 after:origin-left after:rounded-full after:bg-gradient-to-r after:from-chart-1 after:via-chart-3 after:to-chart-5 after:scale-x-100 after:transition-transform after:duration-base after:ease-out focus-visible:ring-[3px] focus-visible:outline-none'
            : 'group data-[popup-open]:bg-accent data-[popup-open]:text-accent-foreground text-muted-foreground hover:bg-accent hover:text-accent-foreground focus-visible:border-ring focus-visible:ring-ring gap-1 rounded-md px-2 py-1.5 text-sm font-medium transition-colors focus-visible:ring-[3px] focus-visible:outline-none'
        }
      >
        {label}
        <ChevronDown
          aria-hidden
          className="group-data-[popup-open]:rotate-180 size-4 transition-transform duration-base ease-out"
        />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" sideOffset={8} className="min-w-44">
        {links.map((link) => (
          <DropdownMenuItem
            key={link.href}
            /*
             * Rendered AS the link rather than wrapping one. A focusable menu
             * item with an anchor inside it is two tab stops for one row, and a
             * reader who middle-clicks a row that only looks like a link gets no
             * new tab and no way to tell that the row was a link at all.
             */
            render={
              <a
                href={link.href}
                target={link.newTab ? '_blank' : undefined}
                rel={link.newTab ? 'noopener noreferrer' : undefined}
                aria-current={link.current ? 'page' : undefined}
                data-current={link.current ? 'true' : undefined}
              />
            }
            className="data-[current]:bg-accent data-[current]:text-accent-foreground data-[current]:font-medium"
          >
            {link.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import type { ReactNode } from 'react'

import type { Mode, PackId } from '../../theming'
import type { SearchDialogMessages } from '../../components/ui/search-dialog'
import { ModeToggle } from './mode-toggle'
import { SearchEntry } from './search-entry'
import { SitesMenu } from './sites-menu'
import { ThemeMenu, type ThemePack } from './theme-menu'
import type { SwitcherProduct } from '../../components/ui/product-switcher'
import type { MobileNavEntry } from './mobile-nav'
import { MobileNav } from './mobile-nav'
import { PrismProvider } from '../../provider/provider'

/** What the control cluster was told to render. Every field is optional. */
export type NavbarControlsProps = {
  /**
   * The product whose mark heads the mobile panel. The drawn `mark` crosses
   * this client boundary as rendered content, the same way a slot does, so a
   * consumer's drawing stays server-drawn while the panel around it is not.
   */
  product: { id: string; name: string; pack?: PackId | null; mark?: ReactNode }
  /** The site's own destinations, for the panel below the row's threshold. */
  nav: readonly MobileNavEntry[]
  /** The accessible name of the panel and of its trigger. */
  navLabel: string
  /** The set of sites, or nothing for a site that is the only one. */
  sites?: readonly SwitcherProduct[]
  /** The `id` of the site the reader is on. */
  currentSiteId?: string
  /** The accessible name of the sites menu. */
  sitesLabel?: string
  /** Where the search index is served from, or nothing for no search. */
  search?: {
    indexUrl: string
    label: string
    hint?: string
    messages: SearchDialogMessages
  }
  /** The packs the chooser offers, or nothing for no chooser. */
  theme?: { label: string; packs?: readonly ThemePack[] }
  /** The two names of the light and dark control, or nothing for no toggle. */
  mode?: { lightLabel: string; darkLabel: string }
  /** The two names of the mobile trigger. */
  mobileLabels: { open: string; close: string }
  /** The pack a reader with no stored choice gets. */
  defaultPack: PackId
  /** The mode a reader with no stored choice gets. */
  defaultMode: Mode
  /** A slot for controls the consumer owns, after the ones above. */
  actions?: React.ReactNode
}

/**
 * The bar's controls, and the only client boundary in the navbar.
 *
 * Everything interactive in a site header is application state: what a reader has
 * chosen, what is open, what a search found. None of it is a fact the bar can be
 * told, so none of it can live in a server Component, and the boundary is drawn
 * here rather than around the whole bar so that the brand lockup and the
 * navigation stay server rendered. That is the arrangement that lets a site keep
 * the rest of its page free of client JavaScript, which is the property three of
 * the five NaniSoft sites are built around.
 *
 * **The provider is mounted here and not in the site's root layout, and that is
 * deliberate.** A provider in the layout would wrap every page and every provider
 * is context, so a page that never renders a control would still ship it. Mounted
 * around five buttons, it ships with the buttons and stops there. It is also the
 * only writer of the two attributes the boot script reads, so a choice made here
 * is a choice the next page load resolves to the same theme.
 *
 * **The order is fixed and it is a reading order, not a preference.** Search first
 * because it is the only control that answers a question the reader arrived with;
 * then the two menus, which are choices about where to be rather than about what to
 * do; then the mode, which is the choice that persists across every site in the
 * family; then the mobile trigger, which is last because it is the only one that
 * appears at the narrow end of the range and appears alone there.
 */
export function NavbarControls(props: NavbarControlsProps) {
  const {
    product,
    nav,
    navLabel,
    sites,
    currentSiteId,
    sitesLabel,
    search,
    theme,
    mode,
    mobileLabels,
    defaultPack,
    defaultMode,
    actions,
  } = props

  const hasThemeControls = Boolean(theme) || Boolean(mode)
  if (!search && !sites && !hasThemeControls && !actions && nav.length === 0) return null

  return (
    <PrismProvider defaultPack={defaultPack} defaultMode={defaultMode}>
      <div className="ms-auto flex items-center gap-2">
        {search ? (
          <SearchEntry
            indexUrl={search.indexUrl}
            label={search.label}
            hint={search.hint}
            messages={search.messages}
          />
        ) : null}

        {sites && sites.length > 0 && sitesLabel ? (
          <SitesMenu sites={sites} currentId={currentSiteId} label={sitesLabel} />
        ) : null}

        {theme ? <ThemeMenu label={theme.label} packs={theme.packs} /> : null}

        {mode ? <ModeToggle lightLabel={mode.lightLabel} darkLabel={mode.darkLabel} /> : null}

        {actions}

        {nav.length > 0 ? (
          <MobileNav
            product={product}
            links={nav}
            label={navLabel}
            openLabel={mobileLabels.open}
            closeLabel={mobileLabels.close}
          />
        ) : null}
      </div>
    </PrismProvider>
  )
}
